export function applyAuditedSentenceCardBreaks(question,{source,book,lesson}){
  // Apply only to audited static SNU questions with the EXACT original source text.
  // Unknown/custom/teacher-edited questions never enter this mapping.
  if(source !== 'snu' || !question || !question.id) return question;
  const id = String(question.id);
  const match = /^SNU-(1A|1B|2A|2B|3A|3B)-(\d{2})-(\d{3})$/.exec(id);
  if(!match || match[1]!==String(book) || Number(match[2])!==Number(lesson)) return question;
  const entry = AUDITED_BOUNDARIES[id];
  if(!entry || entry[0]!==String(question.displaySentence||'')) return question;
  if(!Array.isArray(question.tokens)||question.tokens.length<2||
     !Array.isArray(question.acceptedOrders)||question.acceptedOrders.length!==1) return question;
  // A four-card minimum is mandatory for all approved textbook levels.
  if(!Array.isArray(entry[1])||entry[1].length<4) return question;
  const cards = entry[1].map((text,index)=>[id+'__split_'+index,text]);
  // Optional index 2 is a staged, approved replacement sentence for a source
  // that cannot be fairly split into four meaningful cards.
  return {...question,displaySentence:entry[2]||entry[0],
    tokens:cards,acceptedOrders:[cards.map(card=>card[0])]};
}